// Plan 11: the pure half of the pane body kit (369.26-ENGINE-RULES.md, "Pane body recipe").
//
// A tab body is an imported file, so it can take neither `$` nor an atom (rules 1, 2, 6). It gets
// plain values in (`ctx.body`, `ctx.detailsOpen`) and closures out (`ctx.act`). The closures are
// built in src/registrars/pane.tsx, the one file that holds `$`; everything here is data in, data
// out, so a test imports it directly. Nothing in this file touches `$`, an atom, a hook or the
// environment.
//
// The state is ONE generic key, `body`: a record with one slice per tab. A slice is a bag of JSON
// (no functions, no undefined). A body narrows its own slice with an `isXState` guard, the way
// `isViewModel` narrows the model. Writes are `act.patch(tab, partial)` (merge) and
// `act.update(tab, fn)` (functional update); both run in a press, select or open handler, never in
// a view (rule 4).
import { MINDRIAN_SERVER, TAB_IDS } from '../runtime/ids'
import type { TabId } from '../runtime/ids'

// One tab's slice. An index signature, never a nested `Record<string, unknown>` (rule 9: that
// makes the engine list a phantom state key named Record).
export type BodySlice = { [key: string]: unknown }

export type BodyState = Record<TabId, BodySlice>

// The starting value: one empty slice per tab. Every call returns fresh objects, so no two readers
// ever share a slice.
export function emptyBody(): BodyState {
  return { room: {}, think: {}, sources: {}, review: {} }
}

function isSlice(x: unknown): x is BodySlice {
  return typeof x === 'object' && x !== null && !Array.isArray(x)
}

// A stored value read back as a body: a value that is not an object reads as empty, a tab whose
// slice is missing or not an object reads as an empty slice. The stored value is never mutated.
export function asBody(x: unknown): BodyState {
  const out = emptyBody()
  if (!isSlice(x)) return out
  for (const tab of TAB_IDS) {
    const slice = x[tab]
    if (isSlice(slice)) out[tab] = slice
  }
  return out
}

// A new record with `partial` merged into `rec[tab]`; the other tabs are the same objects. A key
// whose value is `undefined` is removed from the slice (state is JSON: `undefined` does not exist
// there, and "clear this key" must be possible).
export function mergeBody(rec: BodyState, tab: TabId, partial: BodySlice): BodyState {
  const slice: BodySlice = { ...rec[tab] }
  for (const key of Object.keys(partial)) {
    const value = partial[key]
    if (value === undefined) delete slice[key]
    else slice[key] = value
  }
  return { ...rec, [tab]: slice }
}

// A new record with one tab's slice replaced; the other tabs are the same objects.
export function replaceBody(rec: BodyState, tab: TabId, slice: BodySlice): BodyState {
  return { ...rec, [tab]: slice }
}

// The only MCP server a body may reach through `act.io` (Canon Part 8: a body can never reach the
// Brain; the one audited Brain call is plan 16's `act.guidance`). Exact match, nothing else.
export function allowedServer(server: string): boolean {
  return server === MINDRIAN_SERVER
}

// A bare file name under the plugin's assets folder: letters, digits, dot, dash and underscore,
// starting with a letter, digit or underscore, with no parent step. Refuses '', 'a/b', '..',
// '../x' and 'a\\b'.
export function isAssetName(name: string): boolean {
  return /^[A-Za-z0-9_][A-Za-z0-9._-]*$/.test(name) && !name.includes('..')
}

files.src/pane/pane.tsx:
// Plan 07: the pane shell, a pure view. buildPane(el, input, deps) returns the tree for one frame:
// the tab strip first (no title row of its own, C-18), the notes, then the active tab's body. The
// hook file (src/registrars/pane.tsx) reads state and the environment, builds `input` and the
// action closures, and calls this. Nothing here touches `$`: the engine scan follows `$` only in
// the file that holds it (369.26-ENGINE-RULES.md rule 1), which is also why the plan's
// renderPane($, e, deps) is this view function instead.
import type { RenderElement } from 'claude-code'

import { fixFlags } from '../band/alerts'
import { text } from '../copy/text'
import type { ViewModel } from '../model/view-model'
import type { TabId } from '../runtime/ids'
import type { Mode } from '../theme/plain'
import type { Theme } from '../theme/theme'
import { detailsBlock, detailsButton } from './details-block'
import { explainNote } from './explain-note'
import { hintLine } from './hint-line'
import { ink, page } from './ink'
import type { BodyState } from './kit'
import { keysPanel } from './keys-panel'
import { paneLayout } from './layout'
import { EXPLAIN_FOR_TAB, keyList } from './state'
import { tabStrip } from './tab-strip'
import type { Surface } from './tab-strip'
import type { KeySpec, PaneEl, ShellActions, TabBody, TabContext } from './types'

export type { ShellActions } from './types'

export type PaneInput = {
  surface: Surface
  tab: TabId
  // Null when no live model has been read yet and no sample is set: the shell draws only the strip.
  vm: ViewModel | null
  mode: Mode
  theme: Theme | null
  bodyColumns: number
  isFocused: boolean
  working: boolean
  keysOpen: boolean
  explainOpen: boolean
  detailsOpen: Record<TabId, boolean>
  // The `body` state: one slice per tab, handed to the active body as ctx.body (plan 11).
  body: BodyState
  act: ShellActions
}

export type PaneDeps = { bodies: Record<TabId, TabBody | undefined> }

// A body that throws costs nothing: the shell draws without it.
export function safeView(body: TabBody | undefined, ctx: TabContext | null): RenderElement | null {
  if (body === undefined || ctx === null) return null
  try {
    return body.view(ctx)
  } catch {
    return null
  }
}

export function safeKeys(body: TabBody | undefined, ctx: TabContext | null): KeySpec[] {
  if (body === undefined || ctx === null) return []
  try {
    return body.keys(ctx)
  } catch {
    return []
  }
}

export function buildPane(el: PaneEl, input: PaneInput, deps: PaneDeps): RenderElement {
  const { Box, Text } = el
  const { mode, theme, tab } = input
  const layout = paneLayout(input.bodyColumns)
  const body = deps.bodies[tab]
  const ctx: TabContext | null =
    input.vm === null
      ? null
      : {
          el,
          surface: input.surface,
          vm: input.vm,
          theme,
          mode,
          bodyColumns: input.bodyColumns,
          isFocused: input.isFocused,
          tab,
          body: input.body,
          detailsOpen: input.detailsOpen[tab],
          act: input.act,
        }

  const strip = tabStrip(el, {
    tab,
    mode,
    theme,
    layout,
    surface: input.surface,
    onTab: (id) => {
      void input.act.setTab(id)
    },
  })

  // Notes, each at most once: the sample banner, the mode note, the narrow note, the working note.
  const notes: string[] = []
  if (input.vm !== null && input.vm.source === 'sample') notes.push(text('N04'))
  if (mode.note === 'N01') notes.push(text('N01'))
  if (mode.note === 'N03') notes.push(text('N03'))
  if (layout.widthNote) notes.push(text('N05'))
  if (input.working) notes.push(text('P05'))

  const bodyEl = safeView(body, ctx)
  const keys = keyList(body !== undefined, safeKeys(body, ctx), tab)

  const hint = hintLine(el, {
    keys,
    isFocused: input.isFocused,
    bodyColumns: input.bodyColumns,
    keysOpen: input.keysOpen,
    mode,
    theme,
    act: input.act,
  })

  // With nothing to draw from (no model yet) the pane stops at the strip and the hint line.
  if (input.vm === null || ctx === null) {
    return (
      <Box flexDirection="column" width={input.bodyColumns} {...page(mode, theme)}>
        {strip}
        {hint}
        {notes.map((note) => (
          <Text {...ink(mode, theme)}>{note}</Text>
        ))}
      </Box>
    )
  }

  let extra: RenderElement | null = null
  if (body?.detailsExtra !== undefined) {
    try {
      extra = body.detailsExtra(ctx)
    } catch {
      extra = null
    }
  }
  const detailsOpen = input.detailsOpen[tab]

  return (
    <Box flexDirection="column" width={input.bodyColumns} {...page(mode, theme)}>
      {strip}
      {hint}
      {notes.map((note) => (
        <Text {...ink(mode, theme)}>{note}</Text>
      ))}
      {input.keysOpen ? keysPanel(el, { keys, mode, theme, act: input.act, fixes: fixFlags(input.vm) }) : null}
      {input.explainOpen
        ? explainNote(el, { explainId: body?.explainId ?? EXPLAIN_FOR_TAB[tab], mode, theme })
        : null}
      {bodyEl}
      {detailsButton(el, { tab, open: detailsOpen, mode, theme, act: input.act })}
      {detailsOpen ? detailsBlock(el, { vm: input.vm, mode, theme, extra }) : null}
    </Box>
  )
}

files.src/pane/think/lookup.ts:
// Plan 16: the pure half of the one guarded lookup (Canon Part 8, R-24). The Think tab's "Look up
// general guidance" button may cause ONE Brain call, and the only thing that call may carry is the
// name of a method from the framework-name canon. This file decides what counts as such a name and
// maps the answer; the call itself sits in the `act.guidance` closure in src/registrars/pane.tsx
// (the one file that holds `$`), which asks this file before it sends anything.
//
// No value import and no `$` here: tests/test-369.26-part8.cjs loads this file directly through
// Node's own type stripping to prove it agrees with the egress guard on every canon name and every
// room-content canary, so it must stay a plain erasable module.
import type { Actions } from '../types'

// The charset and length the egress guard (lib/core/part8-egress-guard.cjs FRAMEWORK_NAME_RE) and
// Theo itself accept for a framework handle. A name outside it is never sent.
const HANDLE_SHAPE = /^[A-Za-z0-9 '(),./-]{1,128}$/

// The longest text a lookup result may show (UI-SPEC 7.4, MarkdownProps).
export const GUIDANCE_MAX = 10000

// The lowercased canon names found in the text of the framework-names asset, or [] when the text is
// not that file (never throws). An empty list accepts nothing, as the guard does on an empty canon.
export function parseCanon(canonText: string): string[] {
  let doc: unknown
  try {
    doc = JSON.parse(canonText)
  } catch {
    return []
  }
  if (typeof doc !== 'object' || doc === null || Array.isArray(doc)) return []
  const names = (doc as { framework_names?: unknown }).framework_names
  if (!Array.isArray(names)) return []
  const out: string[] = []
  for (const name of names) {
    if (typeof name === 'string' && HANDLE_SHAPE.test(name)) out.push(name.toLowerCase())
  }
  return out
}

// True only for a string that fits the charset and length rule AND equals a canon name after
// lowercasing (never a substring, never a prefix). `canon` is the output of parseCanon.
export function inCanon(handle: unknown, canon: readonly string[]): handle is string {
  if (typeof handle !== 'string' || !HANDLE_SHAPE.test(handle)) return false
  return canon.includes(handle.toLowerCase())
}

// The same check from the text of the framework-names asset (what the closure reads).
export function isCanonicalHandle(handle: unknown, canonText: string): handle is string {
  return inCanon(handle, parseCanon(canonText))
}

export type GuidanceText = { kind: 'ok'; text: string } | { kind: 'failed' }

// The text of a tool reply, `{ content: [{ type: 'text', text }], isError }`: the first text block,
// cut at GUIDANCE_MAX. An error reply, a reply with no text and a blank text are all failed.
export function textFromReply(reply: unknown): GuidanceText {
  if (typeof reply !== 'object' || reply === null || Array.isArray(reply)) return { kind: 'failed' }
  const rec = reply as { content?: unknown; isError?: unknown }
  if (rec.isError === true || !Array.isArray(rec.content)) return { kind: 'failed' }
  for (const block of rec.content) {
    if (typeof block !== 'object' || block === null) continue
    const b = block as { type?: unknown; text?: unknown }
    if (b.type === 'text' && typeof b.text === 'string') {
      if (b.text.trim().length === 0) return { kind: 'failed' }
      return { kind: 'ok', text: b.text.slice(0, GUIDANCE_MAX) }
    }
  }
  return { kind: 'failed' }
}

export type GuidanceResult = GuidanceText | { kind: 'refused' }

// Ask for general guidance on one method. Everything that can go wrong is a result, never a throw:
// a closure that refused the handle is `refused`, and a closure that threw, a rejected call, an
// error reply and a reply with no text are `failed`.
export async function lookupGuidance(act: Pick<Actions, 'guidance'>, handle: string): Promise<GuidanceResult> {
  let answer: Awaited<ReturnType<Actions['guidance']>>
  try {
    answer = await act.guidance(handle)
  } catch {
    return { kind: 'failed' }
  }
  if (answer.kind === 'refused') return { kind: 'refused' }
  if (answer.kind === 'failed') return { kind: 'failed' }
  return textFromReply(answer.reply)
}

