// Plan 11: "What to do next" (UI-SPEC 7.3 SuggestedMovePanel, heading P30). The step is data from the
// model; under it P31 with the reason when one is recorded, else P32. A step that is not recorded
// (M04), unreadable (M03) or still being looked up (M04: the deck has no wording of its own for it)
// is its own words and draws NO button: nothing is made up, and a decision that waits never becomes
// the next step (UI-SPEC 10.4).
//
// The primary button (P33, key next:prefill, hotkey n) only ADDS words to the prompt box: the
// recorded command when the model carries one, else the plain sentence Q01. The person reads it and
// presses Enter. Nothing here submits or runs anything (T-369.26-11-01).
import type { RenderElement } from 'claude-code'

import { text } from '../../copy/text'
import type { ViewModel } from '../../model/view-model'
import { prefillPrompt, prefillRecorded } from '../../runtime/prefill'
import { ground, ink } from '../ink'
import type { TabContext } from '../types'
import { panel } from './panel'

// True when there is a recorded step to act on (so the P33 button is drawn).
export function showsPrefill(vm: ViewModel): boolean {
  return vm.next.step.state === 'ok'
}

export function suggestedMovePanel(ctx: TabContext): RenderElement {
  const { Box, Text, Button } = ctx.el
  const color = ink(ctx.mode, ctx.theme)
  const next = ctx.vm.next
  const step = next.step
  if (step.state !== 'ok') {
    const words = step.state === 'unavailable' ? text('M03') : text('M04')
    return panel(ctx, 'room:next', text('P30'), [
      <Text key="room:next-missing" {...color}>
        {words}
      </Text>,
    ])
  }
  const reasonWords = next.reason.state === 'ok' ? text('P31', { reason: next.reason.value }) : text('P32')
  const command = next.command
  return panel(ctx, 'room:next', text('P30'), [
    <Text key="room:next-step" {...color}>
      {step.value}
    </Text>,
    <Text key="room:next-reason" {...color}>
      {reasonWords}
    </Text>,
    <Box key="next:prefill-ground" {...ground(ctx.mode, ctx.theme, 'where')}>
      <Button
        key="next:prefill"
        label={text('P33')}
        hotkey="n"
        variant="primary"
        onPress={() => {
          // The recorded command when the record carries one (data), else the plain sentence Q01.
          // Both only fill the prompt box and toast P34 or P35.
          void (command !== null ? prefillRecorded(ctx.act, command) : prefillPrompt(ctx.act, 'Q01'))
        }}
      />
    </Box>,
  ])
}

files.src/pane/room/waiting-panel.tsx:
// Plan 11: "Waiting on you" (UI-SPEC 7.3 WaitingPanel, heading P40). None P41, one P42, several P44
// with the real count; a count the model could not read is its own missing words. The jump button
// (P43, hotkey v) is drawn only when at least one decision waits and goes to the Review tab. It is
// `v`, never `d`, because `d` means Decide later inside Review (UI-SPEC 8.2).
import type { RenderElement } from 'claude-code'

import { text } from '../../copy/text'
import { missing } from '../details-block'
import { ground, ink } from '../ink'
import type { TabContext } from '../types'
import { panel } from './panel'

// How many decisions wait, or null when the model could not say.
export function waitingCount(ctx: TabContext): number | null {
  const waiting = ctx.vm.waiting
  return waiting.state === 'ok' ? Math.max(0, Math.floor(waiting.value)) : null
}

export function waitingWords(ctx: TabContext): string {
  const waiting = ctx.vm.waiting
  if (waiting.state !== 'ok') return missing(waiting)
  const n = Math.max(0, Math.floor(waiting.value))
  if (n === 0) return text('P41')
  if (n === 1) return text('P42')
  return text('P44', { n })
}

// True when the P43 button is drawn (the body's key list asks too).
export function showsJump(ctx: TabContext): boolean {
  const n = waitingCount(ctx)
  return n !== null && n >= 1
}

export function waitingPanel(ctx: TabContext): RenderElement {
  const { Box, Text, Button } = ctx.el
  const color = ink(ctx.mode, ctx.theme)
  const children = [
    <Text key="room:waiting-words" {...color}>
      {waitingWords(ctx)}
    </Text>,
  ]
  if (showsJump(ctx)) {
    children.push(
      <Box key="waiting:review-ground" {...ground(ctx.mode, ctx.theme)}>
        <Button
          key="waiting:review"
          label={text('P43')}
          hotkey="v"
          onPress={() => {
            void ctx.act.setTab('review')
          }}
        />
      </Box>,
    )
  }
  return panel(ctx, 'room:waiting', text('P40'), children)
}

